-- Dati strutturati completi dei sei Mono Split
ALTER TABLE products ADD COLUMN tagline VARCHAR(255) NULL AFTER description;
ALTER TABLE products ADD COLUMN badges_text TEXT NULL AFTER tagline;
ALTER TABLE products ADD COLUMN warranty_label VARCHAR(100) NULL AFTER badges_text;
ALTER TABLE product_models ADD COLUMN cooling_kw DECIMAL(6,2) NULL AFTER name;
ALTER TABLE product_models ADD COLUMN seer DECIMAL(6,2) NULL AFTER cooling_kw;
ALTER TABLE product_models ADD COLUMN seer_class VARCHAR(20) NULL AFTER seer;
ALTER TABLE product_models ADD COLUMN heating_kw DECIMAL(6,2) NULL AFTER seer_class;
ALTER TABLE product_models ADD COLUMN scop DECIMAL(6,2) NULL AFTER heating_kw;
ALTER TABLE product_models ADD COLUMN scop_class VARCHAR(20) NULL AFTER scop;
ALTER TABLE product_models ADD COLUMN indoor_unit_code VARCHAR(100) NULL AFTER scop_class;
ALTER TABLE product_models ADD COLUMN outdoor_unit_code VARCHAR(100) NULL AFTER indoor_unit_code;
ALTER TABLE product_accessories ADD COLUMN availability_label VARCHAR(100) NULL AFTER description;
